webpackJsonp([0x83b0e0a2c9d2],{464:function(e,a){e.exports={data:{site:{siteMetadata:{title:"Mihail Eric",subtitle:"Engineer, researcher, educator.",copyright:"Copyright",author:{name:"Mihail Eric",twitter:"mihail_eric"},url:"https://mihaileric.com"}},allMarkdownRemark:{edges:[{node:{fields:{slug:"/posts/complete-artificial-intelligence-undergraduate-course-plan/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"A Complete 4-Year Plan for an Artificial Intelligence Undergraduate Degree",tags:["Machine Learning","A.I.","Deep Learning"],date:"2020-05-24T23:40:37.121"}}},{node:{fields:{slug:"/posts/ml-trends-neurips-2019/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Trends in Machine Learning: NeurIPS 2019 In Review",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-12-15T23:40:37.121"}}},{node:{fields:{slug:"/posts/building-a-deep-learning-computer/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"The Birth of Venus: Building a Deep Learning Computer From Scratch",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-11-03T23:40:37.121"}}},{node:{fields:{slug:"/posts/ml-lesson-curriculum/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"A Comprehensive Introduction to Machine Learning Fundamentals",tags:["Machine Learning","A.I.","Data Science"],date:"2019-09-30T23:46:37.121"}}},{node:{fields:{slug:"/posts/market-basket-analysis/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Market Basket Analysis",tags:["Machine Learning","A.I.","Data Science"],date:"2019-09-02T23:46:37.121"}}},{node:{fields:{slug:"/posts/decision-trees/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Decision Trees",tags:["Machine Learning","A.I.","Data Science"],date:"2019-09-02T23:46:37.121"}}},{node:{fields:{slug:"/posts/k-nearest-neighbors/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Your Closest Neighbors",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-30T23:46:37.121"}}},{node:{fields:{slug:"/posts/model-evaluation/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Model Evaluation",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-28T23:46:37.121"}}},{node:{fields:{slug:"/posts/machine-learning-model-selection/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Why Did You Choose This Model?",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-28T23:46:37.121"}}},{node:{fields:{slug:"/posts/machine-learning-ensembling/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Join the Ensemble",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-28T23:46:37.121"}}},{node:{fields:{slug:"/posts/regularization/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Model Regularization",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-25T23:46:37.121"}}},{node:{fields:{slug:"/posts/principal-components-analysis/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Principal Components Analysis",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-25T23:46:37.121"}}},{node:{fields:{slug:"/posts/feature-selection/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"What Features Do You Want?",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-25T23:46:37.121"}}},{node:{fields:{slug:"/posts/bias-variance-tradeoff/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Controlling Your Model's Bias",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-25T23:46:37.121"}}},{node:{fields:{slug:"/posts/nlp-trends-acl-2019/",tagSlugs:["/tags/natural-language-processing/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Trends in Natural Language Processing: ACL 2019 In Review",tags:["Natural Language Processing","A.I.","Deep Learning"],date:"2019-08-03T23:40:37.121"}}},{node:{fields:{slug:"/posts/what-kmeans-clustering/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"What K-Means",tags:["Machine Learning","A.I.","Data Science"],date:"2019-07-16T23:46:37.121"}}},{node:{fields:{slug:"/posts/recurrent-neural-networks/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Recurrent Neural Networks",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-05-03T23:46:37.121"}}},{node:{fields:{slug:"/posts/convolutional-neural-networks/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Dance Dance Convolution",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-05-03T23:40:37.121"}}},{node:{fields:{slug:"/posts/neural-network-grab-bag/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Neural Network Grab Bag",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-05-03T22:46:37.121"}}},{node:{fields:{slug:"/posts/deep-dive-into-neural-networks/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Deep Dive Into Neural Networks",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-04-28T23:46:37.121"}}},{node:{fields:{slug:"/posts/support-vector-machines/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Basics of Support Vector Machines",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-20T23:46:37.121"}}},{node:{fields:{slug:"/posts/not-so-naive-bayes/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Why So Naive, Bayes?",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-13T23:46:37.121"}}},{node:{fields:{slug:"/posts/introduction-to-logistic-regression/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Introduction to Logistic Regression",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-08T23:46:37.121"}}},{node:{fields:{slug:"/posts/fundamentals-of-linear-regression/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Fundamentals of Linear Regression",tags:["Machine Learning","A.I.","Data Science"],date:"2019-03-15T23:46:37.121"}}},{node:{fields:{slug:"/posts/transformers-attention-in-disguise/",tagSlugs:["/tags/a-i/","/tags/natural-language-processing/","/tags/deep-learning/"]},frontmatter:{title:"Transformers: Attention in Disguise",tags:["A.I.","Natural Language Processing","Deep Learning"],date:"2018-10-22T23:46:37.121"}}},{node:{fields:{slug:"/posts/deep-contextualized-word-representations-elmo/",tagSlugs:["/tags/a-i/","/tags/natural-language-processing/","/tags/deep-learning/"]},frontmatter:{title:"Deep Contextualized Word Representations with ELMo",tags:["A.I.","Natural Language Processing","Deep Learning"],date:"2018-10-08T23:46:37.121"}}},{node:{fields:{slug:"/posts/fast-object-detection-with-fast-rcnn/",tagSlugs:["/tags/machine-learning/","/tags/computer-vision/","/tags/deep-learning/"]},frontmatter:{title:"Fast Object Detection with Fast R-CNN",tags:["Machine Learning","Computer Vision","Deep Learning"],date:"2018-10-01T23:46:37.121"}}},{node:{fields:{slug:"/posts/object-detection-with-rcnn/",tagSlugs:["/tags/machine-learning/","/tags/computer-vision/","/tags/deep-learning/"]},frontmatter:{title:"Object Detection with R-CNN",tags:["Machine Learning","Computer Vision","Deep Learning"],date:"2018-10-01T23:46:37.121"}}},{node:{fields:{slug:"/posts/fundamental-deep-learning-algorithms-to-learn/",tagSlugs:["/tags/a-i/","/tags/deep-learning/","/tags/machine-learning/"]},frontmatter:{title:"Fundamental Deep Learning Algorithms To Learn",tags:["A.I.","Deep Learning","Machine Learning"],date:"2018-08-14T23:46:37.121"}}},{node:{fields:{slug:"/posts/why-all-the-excitement-about-ai/",tagSlugs:["/tags/a-i/","/tags/machine-learning/","/tags/deep-learning/"]},frontmatter:{title:"Why All The Excitement About Artificial Intelligence",tags:["A.I.","Machine Learning","Deep Learning"],date:"2018-08-14T23:46:37.121"}}},{node:{fields:{slug:"/posts/being-a-good-machine-learning-data-scientist/",tagSlugs:["/tags/a-i/","/tags/data-science/","/tags/machine-learning/"]},frontmatter:{title:"Being a Good Machine Learning Engineer/Data Scientist",tags:["A.I.","Data Science","Machine Learning"],date:"2018-08-11T23:46:37.121"}}},{node:{fields:{slug:"/posts/a-software-interview-challenge/",tagSlugs:["/tags/software-engineering/","/tags/interview-prep/"]},frontmatter:{title:"A Software Interview Challenge",tags:["Software Engineering","Interview Prep"],date:"2017-12-24T23:46:37.121"}}},{node:{fields:{slug:"/posts/review-of-sigdial-semdial-2017/",tagSlugs:["/tags/natural-language-processing/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Review of SIGDial/SemDial 2017",tags:["Natural Language Processing","A.I.","Deep Learning"],date:"2017-09-04T23:46:37.121"}}},{node:{fields:{slug:"/posts/a-new-multiturn-dialogue-dataset/",tagSlugs:["/tags/natural-language-processing/","/tags/dataset/","/tags/dialogue/"]},frontmatter:{title:"A New Multi-Turn, Multi-Domain, Task-Oriented Dialogue Dataset",tags:["Natural Language Processing","Dataset","Dialogue"],date:"2017-07-03T23:46:37.121"}}}]},markdownRemark:{id:"/Users/mihaileric/Documents/Projects/mihail911.github.io/src/pages/articles/2018-14-08---Why-All-The-Excitement-About-AI/index.md absPath of file >>> MarkdownRemark",html:'<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/ai-cover-e924b6e53e80e9a21d3850a7a2e301d4-47614.jpeg"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 66.5625%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/jpeg;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Artificial intelligence skyline"\n        title=""\n        src="/static/ai-cover-e924b6e53e80e9a21d3850a7a2e301d4-c6823.jpeg"\n        srcset="/static/ai-cover-e924b6e53e80e9a21d3850a7a2e301d4-dad4f.jpeg 240w,\n/static/ai-cover-e924b6e53e80e9a21d3850a7a2e301d4-1808a.jpeg 480w,\n/static/ai-cover-e924b6e53e80e9a21d3850a7a2e301d4-c6823.jpeg 960w,\n/static/ai-cover-e924b6e53e80e9a21d3850a7a2e301d4-e8e5f.jpeg 1440w,\n/static/ai-cover-e924b6e53e80e9a21d3850a7a2e301d4-47614.jpeg 1600w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Nowadays it’s hard to go to any news source, social media outlet, or downtown bar without hearing the term artificial intelligence thrown around. Thanks to the wonder of <a href="https://www.independent.co.uk/life-style/gadgets-and-tech/news/facebook-artificial-intelligence-ai-chatbot-new-language-research-openai-google-a7869706.html">clickbaity articles</a> and <a href="https://www.youtube.com/watch?v=78-1MlkxyqI">outlandish journalism</a>, artificial intelligence has become synonymous with everything from “that thing” Google and Facebook do (you know, “that thing”) to Skynet and the impending end of humanity as we know it.</p>\n<p>That’s all well and good, but we are still left with some big questions. Why are we talking about this in 2018? Why do people suddenly care so much about artificial intelligence?</p>\n<p>After all, Stanley Kubrick’s <a href="https://en.wikipedia.org/wiki/2001:_A_Space_Odyssey_%28film%29">Hal 9000</a> was stirring the public imagination about artificial intelligence back in 1968! And if we want to go more 21st century with the references, Steven Spielberg’s touching film (literally titled <a href="https://www.imdb.com/title/tt0212720/">A.I. Artificial Intelligence</a>) was released in 2001.</p>\n<p>Moreover, even scientists were talking about AI back in the day. At a historic Dartmouth workshop in 1955, the great computer scientist John McCarthy is <a href="https://ai.stanford.edu/~nilsson/QAI/qai.pdf">credited</a> with describing “the artificial intelligence problem…to be that of making a machine behave in ways that would be called intelligent if a human were so behaving.”</p>\n<p>He also boldly proclaimed that a significant advance can be made in AI if “a carefully selected group of scientists work on it together for a summer.”</p>\n<p>For those of you out there storing canned beans in the bunker for when the machines attack, don’t worry: after many, many summers, we aren’t even close to solving AI.</p>\n<p>So then why did we choose to show up to the party now?</p>\n<p>These are especially relevant questions given that many of the actual techniques we use in modern-day AI systems have been around for decades. Today deep learning is one of the predominant flavors of AI on the market, and many of its core ideas were discovered by David Rumelhart, Geoffrey Hinton, and others <a href="https://www.nature.com/articles/323533a0">back in the 1980s</a>.</p>\n<p>Given all that backstory, I want to discuss how we got to this AI excitement we are feeling today, without appealing to the clickbait-lover inside all of us.</p>\n<p>It’s fair to say that there are at least three reasons why the AI boom has drastically taken off in the past few years:</p>\n<h2>1. Modern-day computing power is changing the landscape of problems we can tackle</h2>\n<p>In 1965, Gordon Moore, the cofounder of Intel, <a href="http://www.lithoguru.com/scientist/CHE323/Moore1995.pdf">announced</a> that the number of components on a computer chip would double every year. Indeed, the number of transistors on a chip is a good measure for the computing power of a machine.</p>\n<p>This claim has become a self-fulfilling prophecy whereby industry chip developers have pursued aggressive technological development programs to sustain the pace of doubling transistor count <strong>roughly every eighteen months</strong>! Moore’s law has been consistently upheld for more than four decades.</p>\n<figure>\n\t\n  <a class="gatsby-resp-image-link" href="/static/transistor-count-over-time-7e1f38cb2e6ac2ba2890f4b97497e8bf-e3b8c.png" style="display: block" target="_blank" rel="noopener">\n  \n  <span class="gatsby-resp-image-wrapper" style="position: relative; display: block; ; max-width: 665px; margin-left: auto; margin-right: auto;">\n    <span class="gatsby-resp-image-background-image" style="padding-bottom: 62.10526315789474%; position: relative; bottom: 0; left: 0; background-image: url(&apos;data:image/png;base64,&apos;); background-size: cover; display: block;">\n      <img class="gatsby-resp-image-image" style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;" alt="Number of transistors on standard microprocessors over time" title="" src="/static/transistor-count-over-time-7e1f38cb2e6ac2ba2890f4b97497e8bf-e3b8c.png" srcset="/static/transistor-count-over-time-7e1f38cb2e6ac2ba2890f4b97497e8bf-3b40e.png 240w,\n/static/transistor-count-over-time-7e1f38cb2e6ac2ba2890f4b97497e8bf-6f75e.png 480w,\n/static/transistor-count-over-time-7e1f38cb2e6ac2ba2890f4b97497e8bf-e3b8c.png 665w" sizes="(max-width: 665px) 100vw, 665px">\n    </span>\n  </span>\n  \n  </a>\n    \n\t<figcaption>Number of transistors on standard microprocessors over time. The y-axis uses a logarithmic scale, hence why the plot is roughly linear</figcaption>\n</figure>\n<p>So what? You can put a lot more electric components on a chip hidden in my laptop. It’s not like I can count them. What’s the big deal?</p>\n<p>This is an amazing feat not just because we’ve done it, but because of <em>what it enables us to do</em>. The dramatic increase in compute has allowed us to build far more powerful algorithms and tools that can perform orders of magnitude more computations per second.</p>\n<p>Just to put things into perspective: it takes an equivalent amount of computations to answer <a href="https://thenextweb.com/google/2012/08/28/fun-fact-one-google-search-uses-computing-power-entire-apollo-space-mission/"><strong>one Google search query</strong></a> as all the calculations done in flight and on ground for the <strong>entire NASA Apollo program</strong>. That means that the compute it takes you to open a browser and search “what is covfefe?” would have sent mankind to the moon in 1969. That’s insane!</p>\n<p>And that’s just CPU (central processing unit) power. Today GPUs (graphical processing units) are the go-to workhorse of building AI systems.</p>\n<p>It turns out that for certain highly-optimized mathematical operations (such as matrix multiplication), GPUs can achieve speeds that are more than <a href="https://medium.com/@andriylazorenko/tensorflow-performance-test-cpu-vs-gpu-79fcd39170c"><strong>10 times faster than CPUs</strong></a>.</p>\n<figure>\n\t<blockquote>\n\t\t<p>With all these new computational superpowers, just imagine the types of questions society can ask and problems it can address.</p>\n\t</blockquote>\n</figure>\n<p>Modern AI systems eat up compute like the Cookie Monster breaking a diet, so this technology has truly broadened our horizons. With all these new computational superpowers, just imagine the types of questions society can ask and problems it can address.</p>\n<h2>2. Dataset sizes have seen unprecedented growth</h2>\n<p>Deep learning has unequivocally become the de facto technique for building artificially intelligent systems, and these algorithms need data to be effective.</p>\n<p>Recently, there have been a number of large public datasets that have become available across domains such as <a href="http://image-net.org/about-overview">image classification</a> and <a href="https://rajpurkar.github.io/SQuAD-explorer/">question answering</a>. Public data is a wonderful resource that academic researchers, you, and I can use to work on cool projects and push the boundaries of human knowledge. </p>\n<p>Additionally, in our increasingly interconnected and global world, the amount of new data being created by individuals is immense! <a href="https://blog.microfocus.com/how-much-data-is-created-on-the-internet-each-day/">Studies</a> indicate that in 2017, <strong>over 500,000 comments are posted and nearly 150,000 photos are uploaded every minute</strong> on Facebook alone.</p>\n<p>Now pause. Let that last line sink in. 500,000 comments and 150,000 photos every minute. That is absolutely crazy!</p>\n<p>You know how many photos were uploaded to online platforms every year back in 1969? You guessed right: 0.</p>\n<p>The growing number of embedded systems (such as phones, tablets, etc.) and online platforms through which users interact have been and are going to continue to be rich sources of data.</p>\n<p>In AI, it is a predominantly accepted folk wisdom that more data leads to better systems. All this data created on a daily basis is powering AI technologies that are helping us derive meaningful insights about our <em>behaviors, preferences, and desires</em>, in ways we have never been able to before.</p>\n<h2>3. Democratization of technological tools are enabling new and innovative solutions to problems</h2>\n<p>More data and increased compute is nice, but those are things most people don’t get excited about on their own.</p>\n<p>Today, the emergence of cloud computing services such as Google Cloud, Microsoft Azure, and Amazon Web Services are making it easier than ever to build scalable, data-driven solutions to various problems. With these services, you can be sitting on your couch at home (or anywhere with WiFi for that matter), and within a few minutes you can have access to industry-grade computing power without burning a hole in your wallet.</p>\n<p>In addition, today we are at a point where powerful scientific computing libraries such as <a href="http://scikit-learn.org/stable/">Scikit-learn</a> and <a href="https://www.tensorflow.org/">Tensorflow</a> are accessible to just about anyone with basic programming proficiency.</p>\n<p>Whereas before deep learning and AI were typically only done by academics with PhDs, today anyone can download Tensorflow and build a neural network <strong>in about an hour</strong>.</p>\n<p>Imagine that: being able to do something in an hour that previously would have taken multiple years of a higher education degree program.</p>\n<p>As a further testament to the appeal of these libraries, as of this writing, <strong>Tensorflow is the sixth most popular repository on <a href="https://github.com/search?q=stars:%3E1&#x26;s=stars&#x26;type=Repositories">Github</a></strong> (popularity based on number of stars).</p>\n<h2>When the Stars Align…</h2>\n<p>When momentous events happen in history, they are usually the product of years of slow build up, followed by some unforeseen occurrence that sets off a tsunami of change.</p>\n<p>Consider as an example the French Revolution. It took years of poor harvests, unpopular taxation, increasing debt, and widening social rifts between the aristocracy and everyday citizens to stir the cauldron of change. However, it was the sudden storming of the Bastille that piggybacked off these circumstances to trigger one of the greatest political revolutions in human history.</p>\n<p>In an analogous fashion, with AI, years of better compute power, increasing dataset sizes, and improved developer toolkits gradually set the stage for something transformative to happen.</p>\n<p>All of these factors came together in 2012 when a team from the University of Toronto led by Geoff Hinton trained a deep learning model that <strong>trounced the competition</strong> in the ImageNet challenge.</p>\n<figure>\n\t<blockquote>\n\t\t<p>For academics, this type of an improvement is career-making. For the rest of the world, this type of an improvement is society-changing.</p>\n\t</blockquote>\n</figure>\n<p>ImageNet was an annual challenge held until 2017 that involved a number of tasks related to classifying and categorizing images. It was the premier competition for building systems with vision capabilities.</p>\n<p>The object recognition portion of the challenge involved giving participating teams several million images labelled according to 1000 categories. The goal was to build a system that could produce the most correct labels for the given images.</p>\n<figure>\n\t\n  <a class="gatsby-resp-image-link" href="/static/imagenet-bird-image-68da8df636ad5d1e074bdff275bbf8c5-78f8c.png" style="display: block" target="_blank" rel="noopener">\n  \n  <span class="gatsby-resp-image-wrapper" style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;">\n    <span class="gatsby-resp-image-background-image" style="padding-bottom: 74.19354838709677%; position: relative; bottom: 0; left: 0; background-image: url(&apos;data:image/png;base64,&apos;); background-size: cover; display: block;">\n      <img class="gatsby-resp-image-image" style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;" alt="An image from the ImageNet dataset. What is this a picture of?" title="" src="/static/imagenet-bird-image-68da8df636ad5d1e074bdff275bbf8c5-3d61e.png" srcset="/static/imagenet-bird-image-68da8df636ad5d1e074bdff275bbf8c5-d182c.png 240w,\n/static/imagenet-bird-image-68da8df636ad5d1e074bdff275bbf8c5-5220f.png 480w,\n/static/imagenet-bird-image-68da8df636ad5d1e074bdff275bbf8c5-3d61e.png 960w,\n/static/imagenet-bird-image-68da8df636ad5d1e074bdff275bbf8c5-78f8c.png 992w" sizes="(max-width: 960px) 100vw, 960px">\n    </span>\n  </span>\n  \n  </a>\n    \n\t<figcaption>An image from the ImageNet dataset. What is this a picture of?</figcaption>\n</figure>\n<p>In the <a href="http://www.image-net.org/challenges/LSVRC/2012/results.html">2012 competition</a>, the Toronto team trained a deep learning model that achieved <strong>16.4% error, compared to the previous best of 25.8%</strong> (lower is better)!</p>\n<p>For academics, this type of an improvement is career-making. For the rest of the world, this type of an improvement is society-changing.</p>\n<p>All of a sudden, systems became good enough at vision where they could be confidently applied to a score of different problems. Today vision companies are appearing every other day claiming to solve a new problem. Moreover, these new-and-improved vision systems are <a href="https://www.iotforall.com/computer-vision-applications-in-daily-life/">already powering</a> many of the technologies we use all the time.</p>\n<p>The 2012 ImageNet Toronto system delivered an unheard of improvement in performance and is widely credited with re-inspiring interest in deep learning research as well as beginning the current artificial intelligence wave. </p>\n<p>Since that momentous achievement, the principles of deep learning have been applied to problems including <a href="https://cs.stanford.edu/people/esteva/nature/">healthcare</a>, <a href="https://cloud.google.com/speech-to-text/">speech recognition</a>, <a href="https://en.wikipedia.org/wiki/Google_Neural_Machine_Translation">translation</a>, <a href="https://www.newscientist.com/article/2113299-googles-deepmind-ai-can-lip-read-tv-shows-better-than-a-pro/">lip reading</a>, <a href="https://devblogs.nvidia.com/deep-learning-self-driving-cars/">self driving cars</a>, and so many other things.</p>\n<p>The excitement is in the air both within academia as well as industry. There is an overwhelming belief that the current age of artificial intelligence has the potential to be the next major technological paradigm shift, similar to the birth of transistors, the rise of network routers, or the standardization of the web.</p>\n<p>If artificial intelligence lives up to its promises, it will revolutionize the world as we know it.</p>\n<p><em>Thanks to <a href="https://twitter.com/SaberaTalukder">Sabera Talukder</a> for all the helpful feedback and insights on early versions of this article.</em></p>',fields:{tagSlugs:["/tags/a-i/","/tags/machine-learning/","/tags/deep-learning/"]},frontmatter:{title:"Why All The Excitement About Artificial Intelligence",tags:["A.I.","Machine Learning","Deep Learning"],date:"2018-08-14T23:46:37.121",description:"Given all the recent buzz around artificial intelligence, I discuss three reasons for why we are seeing such widespread interest in the field today."}}},pathContext:{slug:"/posts/why-all-the-excitement-about-ai/"}}}});
